#include <stdio.h>

int a[2][2] = {{0,0},{1,0}}, id[2][2], g[4][4], cnt;
int dr[4] = {1,0,-1,0}, dc[4] = {0,1,0,-1};

int main() {
    for(int r=0; r<2; r++)
        for(int c=0; c<2; c++)
            if(a[r][c]==0) id[r][c] = cnt++;
    for(int r=0; r<2; r++) {
        for(int c=0; c<2; c++) {
            if(a[r][c]!=0) continue;
            for(int i=0; i<4; i++) {
                int nr = r+dr[i], nc = c+dc[i];
                if(nr>=0 && nr<2 && nc>=0 && nc<2 && a[nr][nc]==0)
                    g[id[r][c]][id[nr][nc]] = 1;
            }
        }
    }
    int sum = 0;
    for(int i=0; i<cnt; i++)
        for(int j=0; j<cnt; j++) sum += g[i][j];
    printf("%d %d", cnt, sum);
    return 0;
}

#include <stdio.h>

int f(int i, int k) {
    if(k==2) return 1;
    if(i==5) return 0;
    return f(i+1,k+1)+f(i+1,k);
}

int main() {
    printf("%d", f(0,0));
    return 0;
}
